"""
verify_apps.py
Verifies whether common application-level file operations still work
once the inode table is exhausted.
Runs continuously, probing every 10 seconds, and clearly reports
pass/fail for each operation at each inode usage level.
"""
import os, sys, time, errno, tempfile, subprocess, sqlite3, shutil

PROBE_DIR = "/root/.openclaw/workspace/file_gen_test/verify_probe"
RESULTS   = "/root/.openclaw/workspace/file_gen_test/verify_results.log"
os.makedirs(PROBE_DIR, exist_ok=True)

# ── helpers ──────────────────────────────────────────────────────────────────

def inode_stats():
    st = os.statvfs("/")
    total = st.f_files
    free  = st.f_ffree
    used  = total - free
    pct   = used / total * 100 if total else 0
    return used, free, pct

def ok(label):  return f"  ✅  {label}"
def fail(label, err): return f"  ❌  {label}: {err}"

# ── individual probes ─────────────────────────────────────────────────────────

def probe_touch():
    p = os.path.join(PROBE_DIR, f"touch_{int(time.time()*1000)}.tmp")
    try:
        fd = os.open(p, os.O_CREAT | os.O_WRONLY, 0o644)
        os.close(fd)
        os.unlink(p)
        return ok("touch / create empty file")
    except OSError as e:
        return fail("touch / create empty file", e)

def probe_write():
    p = os.path.join(PROBE_DIR, f"write_{int(time.time()*1000)}.tmp")
    try:
        with open(p, "w") as f:
            f.write("hello inode world\n")
        os.unlink(p)
        return ok("write text file")
    except OSError as e:
        return fail("write text file", e)

def probe_mkdir():
    p = os.path.join(PROBE_DIR, f"dir_{int(time.time()*1000)}")
    try:
        os.mkdir(p)
        os.rmdir(p)
        return ok("mkdir / create directory")
    except OSError as e:
        return fail("mkdir / create directory", e)

def probe_symlink():
    src = os.path.join(PROBE_DIR, f"sym_{int(time.time()*1000)}.lnk")
    try:
        os.symlink("/etc/hostname", src)
        os.unlink(src)
        return ok("symlink creation")
    except OSError as e:
        return fail("symlink creation", e)

def probe_tempfile():
    try:
        fd, p = tempfile.mkstemp(dir=PROBE_DIR)
        os.close(fd)
        os.unlink(p)
        return ok("tempfile.mkstemp()")
    except OSError as e:
        return fail("tempfile.mkstemp()", e)

def probe_python_open():
    p = os.path.join(PROBE_DIR, f"py_{int(time.time()*1000)}.py")
    try:
        with open(p, "w") as f:
            f.write("x = 1\n")
        os.unlink(p)
        return ok("Python open() write")
    except OSError as e:
        return fail("Python open() write", e)

def probe_sqlite():
    p = os.path.join(PROBE_DIR, f"db_{int(time.time()*1000)}.sqlite")
    try:
        conn = sqlite3.connect(p)
        conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY)")
        conn.commit()
        conn.close()
        os.unlink(p)
        return ok("SQLite DB create + write")
    except Exception as e:
        return fail("SQLite DB create + write", e)

def probe_append_existing():
    """Appending to an EXISTING file should never need a new inode."""
    p = os.path.join(PROBE_DIR, "persistent_append.log")
    try:
        with open(p, "a") as f:
            f.write(f"append at {time.strftime('%H:%M:%S')}\n")
        return ok("append to existing file (no new inode needed)")
    except OSError as e:
        return fail("append to existing file", e)

def probe_read_existing():
    """Reading existing files should always work regardless of inodes."""
    try:
        with open("/etc/hostname") as f:
            _ = f.read()
        return ok("read existing file (/etc/hostname)")
    except OSError as e:
        return fail("read existing file", e)

def probe_shell_redirect():
    try:
        p = os.path.join(PROBE_DIR, f"sh_{int(time.time()*1000)}.out")
        result = subprocess.run(
            f"echo 'shell test' > {p} && rm {p}",
            shell=True, capture_output=True, timeout=5
        )
        if result.returncode == 0:
            return ok("shell echo redirect (bash)")
        else:
            return fail("shell echo redirect", result.stderr.decode().strip())
    except Exception as e:
        return fail("shell echo redirect", e)

PROBES = [
    probe_touch,
    probe_write,
    probe_mkdir,
    probe_symlink,
    probe_tempfile,
    probe_python_open,
    probe_sqlite,
    probe_append_existing,
    probe_read_existing,
    probe_shell_redirect,
]

# ── main loop ─────────────────────────────────────────────────────────────────

print("=" * 70, flush=True)
print("  Application File-Creation Verification — inode exhaustion probe", flush=True)
print("=" * 70, flush=True)

prev_pct = -1
with open(RESULTS, "w") as log:
    log.write("time,iused,ifree,pct,probe,result\n")

    while True:
        used, free, pct = inode_stats()
        ts = time.strftime("%H:%M:%S")

        # Print header every probe cycle
        print(f"\n{'─'*70}", flush=True)
        print(f"  🕐 {ts}  |  IUsed={used:,}  IFree={free:,}  Usage={pct:.2f}%", flush=True)
        print(f"{'─'*70}", flush=True)

        for probe in PROBES:
            result = probe()
            print(result, flush=True)
            label = probe.__name__.replace("probe_", "")
            status = "PASS" if "✅" in result else "FAIL"
            log.write(f"{ts},{used},{free},{pct:.4f},{label},{status}\n")
        log.flush()

        if free == 0:
            print(f"\n🚫 FREE INODES = 0  — inode table fully exhausted.", flush=True)
            print("   Sleeping 30s then doing one final probe pass...", flush=True)
            time.sleep(30)
            # One final pass
            used, free, pct = inode_stats()
            print(f"\n{'='*70}", flush=True)
            print(f"  FINAL PASS — IUsed={used:,}  IFree={free:,}  Usage={pct:.2f}%", flush=True)
            print(f"{'='*70}", flush=True)
            for probe in PROBES:
                print(probe(), flush=True)
            break

        prev_pct = pct
        time.sleep(10)

print(f"\n✅ Verification complete. Results saved to {RESULTS}", flush=True)
